        license = License.objects.using(alias).filter(driver_id=driver.pk).first()
        face = Face.objects.using(alias).filter(driver_id=driver.pk).first()
        complete = all((driver.full_name.strip(), driver.date_of_birth, driver.phone.strip(), driver.address.strip(),
                        license and license.license_number and license.license_class and license.front_image_url and license.back_image_url,
                        face and face.face_image_url and face.embedding))
