        if not complete:
            status = 'INCOMPLETE'
        elif status == 'APPROVED':
            # Previous approval only covered personal details; require an overall review.
            status = 'PENDING'
        Driver.objects.using(alias).filter(pk=driver.pk).update(approval_status=status, updated_at=timezone.now())


